html:
{{ print_control(doc) }}
{%- macro v(value) -%}{{ (value or "") | e }}{%- endmacro -%}
{%- macro day(value) -%}{{ frappe.utils.format_date(value) if value else "" }}{%- endmacro -%}
{%- macro who(user) -%}{{ v(frappe.db.get_value("User", user, "full_name") if user else "") }}{%- endmacro -%}
{%- macro dots(n) -%}{{ "&hellip;" * n }}{%- endmacro -%}
{%- set logo = frappe.db.get_single_value("HRMS Addon Branding", "company_logo") -%}
{%- set employee = frappe.get_doc("Employee", doc.employee) -%}
<style>
.lpl-order { font-family: Cambria, Georgia, serif; font-size: 12.5px; color: #000; line-height: 1.6; }
.lpl-order p { margin: 0 0 10px; }
.lpl-order h3 { font-size: 15px; font-weight: bold; text-align: center; text-decoration: underline; margin: 8px 0 14px; }
.lpl-order h4 { font-size: 12.5px; font-weight: bold; margin: 18px 0 8px; border-bottom: 1px solid #000; }
.lpl-order .logo { text-align: right; margin: 0 0 10px; }
.lpl-order .line { margin: 0 0 8px; }
.lpl-order .box { display: inline-block; width: 11px; height: 11px; border: 1px solid #000; margin: 0 6px 0 14px; vertical-align: middle; }
</style>
<div class="lpl-order">
{% if logo %}<p class="logo"><img src="{{ logo }}" style="max-height:56px"></p>{% endif %}
<h3>MEDICAL TREATMENT ORDER</h3>
<p class="line"><b>Order No.</b> {{ v(doc.name) }} &nbsp; &nbsp; <b>Issued on</b> {{ day(doc.issued_on) }}{% if doc.valid_until %} &nbsp; &nbsp; <b>Valid until</b> {{ day(doc.valid_until) }}{% endif %}</p>
<p class="line"><b>To:</b> The Doctor in Charge, {{ v(doc.hospital) }}</p>
<p>Please examine and treat the employee named below, sent to you by {{ v(doc.company) }}.</p>
<p class="line"><b>Name:</b> {{ v(doc.employee_name) }} &nbsp; &nbsp; <b>Employee No.:</b> {{ v(employee.employee_number or doc.employee) }}</p>
<p class="line"><b>Plant:</b> {{ v(doc.branch) }} &nbsp; &nbsp; <b>Department:</b> {{ v(doc.department) }} &nbsp; &nbsp; <b>Designation:</b> {{ v(doc.designation) }}</p>
<p class="line"><b>To be treated for:</b> {{ v(doc.complaint) }}</p>
{% if doc.safety_incident %}<p class="line"><b>Safety incident:</b> {{ v(doc.safety_incident) }}</p>{% endif %}
<p class="line"><b>Issued by:</b> {{ who(doc.issued_by) }}, EHS Officer &nbsp; &nbsp; Signature {{ dots(14) }}</p>
<h4>For the hospital</h4>
<p class="line">Diagnosis {{ dots(60) }}</p>
<p class="line">{{ dots(70) }}</p>
<p class="line">Treatment given {{ dots(55) }}</p>
<p class="line">{{ dots(70) }}</p>
<p class="line"><b>Recommendation:</b><span class="box"></span>Rest for {{ dots(6) }} days from {{ dots(12) }}<span class="box"></span>Light duty<span class="box"></span>Fit to work<span class="box"></span>Unfit for work</p>
<p class="line">Light work allowed {{ dots(52) }}</p>
<p class="line">Doctor's name {{ dots(24) }} Signature {{ dots(14) }} Date {{ dots(12) }}</p>
<p class="line">Hospital stamp</p>
<p>&nbsp;</p>
<p><em>Please give this form, or the doctor's report, back to the EHS Officer.</em></p>
</div>
